// Функция setup выполняется один раз при старте микроконтроллера
void setup() {
  // Настраиваем пин встроенного светодиода как выход
  pinMode(LED_BUILTIN, OUTPUT);
}

// Функция loop выполняется бесконечно после setup
void loop() {
  digitalWrite(LED_BUILTIN, HIGH); // Включаем светодиод (подаём HIGH)
  delay(1000);                     // Ждём 1000 мс (1 секунда)
  digitalWrite(LED_BUILTIN, LOW);  // Выключаем светодиод (подаём LOW)
  delay(1000);                     // Ждём ещё 1 секунду
}
